package com.campusconnect.dao;
import com.campusconnect.exception.DatabaseException; import com.campusconnect.model.Complaint; import com.campusconnect.util.DatabaseConnection; import java.sql.*; import java.util.*;
public class ComplaintDAO { private Complaint map(ResultSet r)throws SQLException{Complaint x=new Complaint();x.setId(r.getInt("id"));x.setStudentId(r.getInt("student_id"));x.setStudentName(r.getString("student_name"));x.setCategory(r.getString("category"));x.setDescription(r.getString("description"));x.setPriority(r.getString("priority"));x.setStatus(r.getString("status"));x.setResolutionRemarks(r.getString("resolution_remarks"));x.setCreatedAt(r.getTimestamp("created_at").toLocalDateTime());return x;}
 public List<Complaint> findByStudent(int sid){return query("WHERE c.student_id=?",sid);} public List<Complaint> findAll(){return query("",null);} private List<Complaint> query(String where,Integer id){List<Complaint> a=new ArrayList<>();String sql="SELECT c.*,s.name student_name FROM complaints c JOIN students s ON s.user_id=c.student_id "+where+" ORDER BY c.created_at DESC";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){if(id!=null)p.setInt(1,id);try(ResultSet r=p.executeQuery()){while(r.next())a.add(map(r));}}catch(SQLException e){throw new DatabaseException("Could not load complaints.",e);}return a;}
 public void insert(Complaint x){String sql="INSERT INTO complaints(student_id,category,description,priority,status) VALUES(?,?,?,?, 'Pending')";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setInt(1,x.getStudentId());p.setString(2,x.getCategory());p.setString(3,x.getDescription());p.setString(4,x.getPriority());p.executeUpdate();}catch(SQLException e){throw new DatabaseException("Could not create complaint.",e);}}
 public void updateStatus(int id,String status,String priority,String remarks){String sql="UPDATE complaints SET status=?,priority=?,resolution_remarks=? WHERE id=?";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,status);p.setString(2,priority);p.setString(3,remarks);p.setInt(4,id);p.executeUpdate();}catch(SQLException e){throw new DatabaseException("Could not update complaint.",e);}}
 public void delete(int id){execute("DELETE FROM complaints WHERE id=?",id);} public int countStatus(String status){try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM complaints WHERE status=?")){p.setString(1,status);try(ResultSet r=p.executeQuery()){r.next();return r.getInt(1);}}catch(SQLException e){throw new DatabaseException("Could not read complaint statistics.",e);}} private void execute(String sql,int id){try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setInt(1,id);p.executeUpdate();}catch(SQLException e){throw new DatabaseException("Database operation failed.",e);}}
}
